class Solution:
    def solve(self, arr):
        if not arr:
            return 0

        include = max(arr[0], 0)
        exclude = 0

        for i in range(1, len(arr)):
            new_exclude = max(include, exclude)
            include = exclude + arr[i]
            exclude = new_exclude

        return max(include, exclude)
